sys_script_fix.script:
(function run() {
	// Limpa a view da preferência do usuário para que utilize a default
	var upd = new global.GlideQuery('sys_user_preference')
		.where('name', 'cmdb_ci_business_app.view')
		.orWhere('name', 'cmdb_ci_business_app_list.view')
		.updateMultiple({ value: null });
	gs.info('[S047 - pós implantação] ' + JSON.stringify(upd));
})();
